1	import { z } from "zod";
2	import {
3	  AUTH_BASE_URL_MODES,
4	  BIND_MODES,
5	  DEPLOYMENT_EXPOSURES,
6	  DEPLOYMENT_MODES,
7	  DEPLOYMENT_PLATFORMS,
8	  SECRET_PROVIDERS,
9	  STORAGE_PROVIDERS,
10	} from "./constants.js";
11	import { validateConfiguredBindMode } from "./network-bind.js";
12	
13	export const configMetaSchema = z.object({
14	  version: z.literal(1),
15	  updatedAt: z.string(),
16	  source: z.enum(["onboard", "configure", "doctor"]),
17	});
18	
19	export const llmConfigSchema = z.object({
20	  provider: z.enum(["claude", "openai"]),
21	  apiKey: z.string().optional(),
22	});
23	
24	export const databaseBackupConfigSchema = z.object({
25	  enabled: z.boolean().default(true),
26	  intervalMinutes: z.number().int().min(1).max(7 * 24 * 60).default(60),
27	  retentionDays: z.number().int().min(1).max(3650).default(7),
28	  dir: z.string().default("~/.paperclip/instances/default/data/backups"),
29	});
30	
31	export const databaseConfigSchema = z.object({
32	  mode: z.enum(["embedded-postgres", "postgres"]).default("embedded-postgres"),
33	  connectionString: z.string().optional(),
34	  embeddedPostgresDataDir: z.string().default("~/.paperclip/instances/default/db"),
35	  embeddedPostgresPort: z.number().int().min(1).max(65535).default(54329),
36	  backup: databaseBackupConfigSchema.default({
37	    enabled: true,
38	    intervalMinutes: 60,
39	    retentionDays: 7,
40	    dir: "~/.paperclip/instances/default/data/backups",
41	  }),
42	});
43	
44	export const loggingConfigSchema = z.object({
45	  mode: z.enum(["file", "cloud"]),
46	  logDir: z.string().default("~/.paperclip/instances/default/logs"),
47	});
48	
49	export const serverConfigSchema = z.object({
50	  deploymentMode: z.enum(DEPLOYMENT_MODES).default("local_trusted"),
51	  deploymentPlatform: z.enum(DEPLOYMENT_PLATFORMS).default("node"),
52	  exposure: z.enum(DEPLOYMENT_EXPOSURES).default("private"),
53	  bind: z.enum(BIND_MODES).optional(),
54	  customBindHost: z.string().optional(),
55	  host: z.string().default("127.0.0.1"),
56	  port: z.number().int().min(1).max(65535).default(3100),
57	  allowedHostnames: z.array(z.string().min(1)).default([]),
58	  serveUi: z.boolean().default(true),
59	});
60	
61	export const authConfigSchema = z.object({
62	  baseUrlMode: z.enum(AUTH_BASE_URL_MODES).default("auto"),
63	  publicBaseUrl: z.string().url().optional(),
64	  disableSignUp: z.boolean().default(false),
65	});
66	
67	export const storageLocalDiskConfigSchema = z.object({
68	  baseDir: z.string().default("~/.paperclip/instances/default/data/storage"),
69	});
70	
71	export const storageS3ConfigSchema = z.object({
72	  bucket: z.string().min(1).default("paperclip"),
73	  region: z.string().min(1).default("us-east-1"),
74	  endpoint: z.string().optional(),
75	  prefix: z.string().default(""),
76	  forcePathStyle: z.boolean().default(false),
77	});
78	
79	export const storageR2ConfigSchema = z.object({
80	  bucket: z.string().min(1).default("paperclip"),
81	  prefix: z.string().default(""),
82	  accountId: z.string().optional(),
83	});
84	
85	export const storageConfigSchema = z.object({
86	  provider: z.enum(STORAGE_PROVIDERS).default("local_disk"),
87	  localDisk: storageLocalDiskConfigSchema.default({
88	    baseDir: "~/.paperclip/instances/default/data/storage",
89	  }),
90	  s3: storageS3ConfigSchema.default({
91	    bucket: "paperclip",
92	    region: "us-east-1",
93	    prefix: "",
94	    forcePathStyle: false,
95	  }),
96	  r2: storageR2ConfigSchema.default({
97	    bucket: "paperclip",
98	    prefix: "",
99	  }),
100	});
101	
102	export const secretsLocalEncryptedConfigSchema = z.object({
103	  keyFilePath: z.string().default("~/.paperclip/instances/default/secrets/master.key"),
104	});
105	
106	export const secretsConfigSchema = z.object({
107	  provider: z.enum(SECRET_PROVIDERS).default("local_encrypted"),
108	  strictMode: z.boolean().default(false),
109	  localEncrypted: secretsLocalEncryptedConfigSchema.default({
110	    keyFilePath: "~/.paperclip/instances/default/secrets/master.key",
111	  }),
112	});
113	
114	export const telemetryConfigSchema = z.object({
115	  enabled: z.boolean().default(true),
116	}).default({});
117	
118	export const paperclipConfigSchema = z
119	  .object({
120	    $meta: configMetaSchema,
121	    llm: llmConfigSchema.optional(),
122	    database: databaseConfigSchema,
123	    logging: loggingConfigSchema,
124	    server: serverConfigSchema,
125	    telemetry: telemetryConfigSchema,
126	    auth: authConfigSchema.default({
127	      baseUrlMode: "auto",
128	      disableSignUp: false,
129	    }),
130	    storage: storageConfigSchema.default({
131	      provider: "local_disk",
132	      localDisk: {
133	        baseDir: "~/.paperclip/instances/default/data/storage",
134	      },
135	      s3: {
136	        bucket: "paperclip",
137	        region: "us-east-1",
138	        prefix: "",
139	        forcePathStyle: false,
140	      },
141	    }),
142	    secrets: secretsConfigSchema.default({
143	      provider: "local_encrypted",
144	      strictMode: false,
145	      localEncrypted: {
146	        keyFilePath: "~/.paperclip/instances/default/secrets/master.key",
147	      },
148	    }),
149	  })
150	  .superRefine((value, ctx) => {
151	    if (value.server.deploymentMode === "local_trusted" && value.server.exposure !== "private") {
152	      ctx.addIssue({
153	        code: z.ZodIssueCode.custom,
154	        message: "server.exposure must be private when deploymentMode is local_trusted",
155	        path: ["server", "exposure"],
156	      });
157	    }
158	
159	    for (const message of validateConfiguredBindMode({
160	      deploymentMode: value.server.deploymentMode,
161	      deploymentExposure: value.server.exposure,
162	      bind: value.server.bind,
163	      host: value.server.host,
164	      customBindHost: value.server.customBindHost,
165	    })) {
166	      ctx.addIssue({
167	        code: z.ZodIssueCode.custom,
168	        message,
169	        path: message.includes("customBindHost") ? ["server", "customBindHost"] : ["server", "bind"],
170	      });
171	    }
172	
173	    if (value.auth.baseUrlMode === "explicit" && !value.auth.publicBaseUrl) {
174	      ctx.addIssue({
175	        code: z.ZodIssueCode.custom,
176	        message: "auth.publicBaseUrl is required when auth.baseUrlMode is explicit",
177	        path: ["auth", "publicBaseUrl"],
178	      });
179	    }
180	
181	    if (value.server.exposure === "public" && value.auth.baseUrlMode !== "explicit") {
182	      ctx.addIssue({
183	        code: z.ZodIssueCode.custom,
184	        message: "auth.baseUrlMode must be explicit when deploymentMode=authenticated and exposure=public",
185	        path: ["auth", "baseUrlMode"],
186	      });
187	    }
188	
189	    if (value.server.exposure === "public" && !value.auth.publicBaseUrl) {
190	      ctx.addIssue({
191	        code: z.ZodIssueCode.custom,
192	        message: "auth.publicBaseUrl is required when deploymentMode=authenticated and exposure=public",
193	        path: ["auth", "publicBaseUrl"],
194	      });
195	    }
196	  });
197	
198	export type PaperclipConfig = z.infer<typeof paperclipConfigSchema>;
199	export type LlmConfig = z.infer<typeof llmConfigSchema>;
200	export type DatabaseConfig = z.infer<typeof databaseConfigSchema>;
201	export type LoggingConfig = z.infer<typeof loggingConfigSchema>;
202	export type ServerConfig = z.infer<typeof serverConfigSchema>;
203	export type StorageConfig = z.infer<typeof storageConfigSchema>;
204	export type StorageLocalDiskConfig = z.infer<typeof storageLocalDiskConfigSchema>;
205	export type StorageS3Config = z.infer<typeof storageS3ConfigSchema>;
206	export type StorageR2Config = z.infer<typeof storageR2ConfigSchema>;
207	export type SecretsConfig = z.infer<typeof secretsConfigSchema>;
208	export type SecretsLocalEncryptedConfig = z.infer<typeof secretsLocalEncryptedConfigSchema>;
209	export type AuthConfig = z.infer<typeof authConfigSchema>;
210	export type TelemetryConfig = z.infer<typeof telemetryConfigSchema>;
211	export type ConfigMeta = z.infer<typeof configMetaSchema>;
212	export type DatabaseBackupConfig = z.infer<typeof databaseBackupConfigSchema>;
